      var x = ADJ.x + (j - 1) * ADJ.p, y = ADJ.y + (i - 1) * ADJ.p;
      var r = gAdjCells.rect(ADJ.c, ADJ.c).radius(4).move(x, y)
        .fill(v ? C.slateFill : '#ffffff')
        .stroke({ color: v ? C.slateFill : C.cellEdge, width: 2 })
        .css('cursor', 'pointer');
      r.on('mousemove', function (ev) {
        showTooltip(v ? ('A[' + i + ',' + j + '] = 1 : nodes ' + i + ' and ' + j + ' are connected'
          : '') || '' : ('A[' + i + ',' + j + '] = 0 : no edge between ' + i + ' and ' + j), ev);
      }).on('mouseleave', hideTooltip)
        .on('click', function () { if (v) pickEdge(ei); else pickNode(i); });
      adjCells.push({ r: r, i: i, j: j, v: v, x: x, y: y });
    })(i3, j3);
  }
}

/* =====================  PANEL c) NODE DATA X  ===================== */
var XM = { x: 1398, y: 58, c: 32, p: 38 };
richLabel(gX, [{ t: 'c)' }], 1178, 48, { size: 30, anchor: 'start', fill: C.grey });
richLabel(gX, [{ t: 'Node' }], 1370, 100, { size: 27, anchor: 'end', fill: C.rustText });
richLabel(gX, [{ t: 'data, ' }, { t: 'X', bold: true }], 1370, 138, { size: 27, anchor: 'end', fill: C.rustText });
richLabel(gX, [{ t: 'D', italic: true }, { t: ' × ' }, { t: 'N', italic: true }], 1370, 178, { size: 25, anchor: 'end', fill: C.rustText });

var xCells = [], xColHead = {};
var gXCells = gX.group();
var xRings = gX.group();
for (var j4 = 1; j4 <= 6; j4++) {
  xColHead[j4] = richLabel(gX, [{ t: String(j4) }], XM.x + (j4 - 1) * XM.p + XM.c / 2, XM.y - 12, { size: 23, fill: C.grey });
}
for (var r4 = 1; r4 <= 5; r4++) {
  for (var c4 = 1; c4 <= 6; c4++) {
    (function (row, col) {
      var x = XM.x + (col - 1) * XM.p, y = XM.y + (row - 1) * XM.p;
      var rc = gXCells.rect(XM.c, XM.c).radius(4).move(x, y)
        .fill(ORANGES[nodeFeat[col][row - 1]]).stroke({ width: 0 }).css('cursor', 'pointer');
      rc.on('mousemove', function (ev) { showTooltip('X[' + row + ',' + col + '] : feature ' + row + ' of node ' + col, ev); })
        .on('mouseleave', hideTooltip)
        .on('click', function () { pickNode(col); });
      xCells.push({ r: rc, row: row, col: col });
    })(r4, c4);
  }
}

/* =====================  PANEL d) EDGE DATA E  ===================== */
var EM = { x: 1352, y: 406, c: 32, p: 38 };
richLabel(gE, [{ t: 'd)' }], 1170, 380, { size: 30, anchor: 'start', fill: C.grey });
richLabel(gE, [{ t: 'Edge' }], 1320, 442, { size: 27, anchor: 'end', fill: C.tealText });
richLabel(gE, [{ t: 'data, ' }, { t: 'E', bold: true }], 1320, 480, { size: 27, anchor: 'end', fill: C.tealText });
richLabel(gE, [{ t: 'D', italic: true }, { t: 'E', italic: true, sub: true }, { t: ' × ' }, { t: 'E', italic: true }], 1320, 520, { size: 25, anchor: 'end', fill: C.tealText });

var eCells = [], eColHeadA = {}, eColHeadB = {};
var gECells = gE.group();
var eRings = gE.group();
for (var kk = 0; kk < edges.length; kk++) {
  var hx = EM.x + kk * EM.p + EM.c / 2;
  eColHeadA[kk] = richLabel(gE, [{ t: String(edges[kk].a) }], hx, EM.y - 42, { size: 23, fill: C.grey });
  eColHeadB[kk] = richLabel(gE, [{ t: String(edges[kk].b) }], hx, EM.y - 12, { size: 23, fill: C.grey });
}
for (var r5 = 1; r5 <= 4; r5++) {
  for (var c5 = 0; c5 < edges.length; c5++) {
    (function (row, col) {
      var x = EM.x + col * EM.p, y = EM.y + (row - 1) * EM.p;
      var rc = gECells.rect(EM.c, EM.c).radius(4).move(x, y)
        .fill(TEALS[edgeFeat[col][row - 1]]).stroke({ width: 0 }).css('cursor', 'pointer');
      rc.on('mousemove', function (ev) {
        showTooltip('E[' + row + ',' + (col + 1) + '] : feature ' + row + ' of edge ' + edges[col].a + '–' + edges[col].b, ev);
      }).on('mouseleave', hideTooltip)
        .on('click', function () { pickEdge(col); });
      eCells.push({ r: rc, row: row, col: col });
    })(r5, c5);
  }
}

/* =====================  HIGHLIGHT LOGIC  ===================== */
function ringRect(g, x, y, w, h, strong) {
  return g.rect(w, h).radius(7).move(x, y).fill('none')
    .stroke({ color: C.acc, width: strong ? 4 : 2.5, opacity: strong ? 1 : 0.75 });
}

function refresh() {
  var f = state.focus;
  gGraph.opacity(f === 'all' || f === 'a' ? 1 : 0.11);
  gAdj.opacity(f === 'all' || f === 'b' ? 1 : 0.11);
  gX.opacity(f === 'all' || f === 'c' ? 1 : 0.11);
  gE.opacity(f === 'all' || f === 'd' ? 1 : 0.11);

  var n = state.node, ek = state.edge;
  var se = (ek !== null) ? edges[ek] : null;
  var sel = (n !== null) || (se !== null);

  /* graph */
  for (var a = 0; a < nodeEls.length; a++) {
    var ne = nodeEls[a];
    var hi = (n === ne.id) || (se && (se.a === ne.id || se.b === ne.id));
    ne.g.opacity(sel && !hi ? 0.18 : 1);
    ne.sg.opacity(sel && !hi ? 0.18 : 1);
    ne.circle.stroke({ color: (n === ne.id) ? C.acc : C.rust, width: (n === ne.id) ? 6 : 3.5 });
    ne.ring.opacity(n === ne.id ? 1 : 0);
  }
  for (var b = 0; b < edgeEls.length; b++) {
    var ee = edgeEls[b];
    var hiE = (ek === b) || (n !== null && (edges[b].a === n || edges[b].b === n));
    ee.g.opacity(sel && !hiE ? 0.15 : 1);
    ee.sg.opacity(sel && !hiE ? 0.15 : 1);
    ee.line.stroke({ color: ek === b ? C.acc : C.slate, width: ek === b ? 5.5 : 3 });
    ee.ring.opacity(ek === b ? 1 : 0);
  }

  /* adjacency */
  adjRings.clear();
  for (var c = 0; c < adjCells.length; c++) {
    var cc = adjCells[c];
    var hiC = false;
    if (n !== null && (cc.i === n || cc.j === n)) hiC = true;
    if (se && ((cc.i === se.a && cc.j === se.b) || (cc.i === se.b && cc.j === se.a))) hiC = true;
    cc.r.opacity(sel && !hiC ? 0.2 : 1);
  }
  for (var h = 1; h <= 6; h++) {
    var onH = (n === h) || (se && (se.a === h || se.b === h));
    adjColHead[h].fill(onH ? C.acc : C.grey).font({ weight: onH ? 'bold' : 'normal' });
    adjRowHead[h].fill(onH ? C.acc : C.grey).font({ weight: onH ? 'bold' : 'normal' });
  }
  var gw = 6 * ADJ.p - ADJ.p + ADJ.c;
  if (n !== null) {
    ringRect(adjRings, ADJ.x - 5, ADJ.y + (n - 1) * ADJ.p - 5, gw + 10, ADJ.c + 10, true);
    ringRect(adjRings, ADJ.x + (n - 1) * ADJ.p - 5, ADJ.y - 5, ADJ.c + 10, gw + 10, true);
  }
  if (se) {
    ringRect(adjRings, ADJ.x + (se.b - 1) * ADJ.p - 5, ADJ.y + (se.a - 1) * ADJ.p - 5, ADJ.c + 10, ADJ.c + 10, true);
    ringRect(adjRings, ADJ.x + (se.a - 1) * ADJ.p - 5, ADJ.y + (se.b - 1) * ADJ.p - 5, ADJ.c + 10, ADJ.c + 10, true);
  }

  /* node data X */
  xRings.clear();
  for (var d = 0; d < xCells.length; d++) {
    var xc = xCells[d];
    var hiX = (n === xc.col) || (se && (se.a === xc.col || se.b === xc.col));
    xc.r.opacity(sel && !hiX ? 0.2 : 1);
  }
  for (var hh = 1; hh <= 6; hh++) {
    var onX = (n === hh) || (se && (se.a === hh || se.b === hh));
    xColHead[hh].fill(onX ? C.acc : C.grey).font({ weight: onX ? 'bold' : 'normal' });
  }
  var xh = 5 * XM.p - XM.p + XM.c;
  if (n !== null) ringRect(xRings, XM.x + (n - 1) * XM.p - 5, XM.y - 5, XM.c + 10, xh + 10, true);
  if (se) {
    ringRect(xRings, XM.x + (se.a - 1) * XM.p - 5, XM.y - 5, XM.c + 10, xh + 10, false);
    ringRect(xRings, XM.x + (se.b - 1) * XM.p - 5, XM.y - 5, XM.c + 10, xh + 10, false);
  }

  /* edge data E */
  eRings.clear();
  for (var g2 = 0; g2 < eCells.length; g2++) {
    var ec = eCells[g2];
    var inc = (n !== null && (edges[ec.col].a === n || edges[ec.col].b === n));
    var hiEE = (ek === ec.col) || inc;
    ec.r.opacity(sel && !hiEE ? 0.2 : 1);
  }
  for (var m = 0; m < edges.length; m++) {
    var onE = (ek === m) || (n !== null && (edges[m].a === n || edges[m].b === n));
    eColHeadA[m].fill(onE ? C.acc : C.grey).font({ weight: onE ? 'bold' : 'normal' });
    eColHeadB[m].fill(onE ? C.acc : C.grey).font({ weight: onE ? 'bold' : 'normal' });
  }
  var eh = 4 * EM.p - EM.p + EM.c;
  if (ek !== null) ringRect(eRings, EM.x + ek * EM.p - 5, EM.y - 5, EM.c + 10, eh + 10, true);
  if (n !== null) {
    for (var q = 0; q < edges.length; q++) {
      if (edges[q].a === n || edges[q].b === n) ringRect(eRings, EM.x + q * EM.p - 5, EM.y - 5, EM.c + 10, eh + 10, false);
    }
  }

  /* info text */
  var info = document.getElementById('selInfo');
  if (info) {
    if (n !== null) {
      info.textContent = 'Node ' + n + ': row ' + n + ' and column ' + n + ' of A (mirror images), column ' + n + ' of X, ' + degree(n) + ' columns of E.';
    } else if (se) {
      info.textContent = 'Edge ' + se.a + '–' + se.b + ': column ' + (ek + 1) + ' of E, and the two cells (' + se.a + ',' + se.b + ') & (' + se.b + ',' + se.a + ') of A.';
    } else {
      info.textContent = '';
    }
  }
}

/* =====================  INTERACTION  ===================== */
function pickNode(id) {
  state.node = id; state.edge = null;
  var s1 = document.getElementById('selectNodeInput'); if (s1) s1.value = String(id);
  var s2 = document.getElementById('selectEdgeInput'); if (s2) s2.value = '';
  refresh();
  showPopup('Node ' + id,
    'Node ' + id + ' has degree ' + degree(id) + '. In the adjacency matrix A it owns row ' + id + ' AND column ' + id +
    ' — the two are mirror images of each other because the edges are undirected, and A[' + id + ',' + id + '] = 0 since a node is not its own neighbour. ' +
    'Its D = 5 attributes live in exactly one place: column ' + id + ' of the node data matrix X.');
}
function pickEdge(k) {
  state.edge = k; state.node = null;
  var s1 = document.getElementById('selectNodeInput'); if (s1) s1.value = '';
  var s2 = document.getElementById('selectEdgeInput'); if (s2) s2.value = String(k);
  refresh();
  var e = edges[k];
  showPopup('Edge ' + e.a + '–' + e.b,
    'Connectivity and attributes are stored separately. This edge shows up twice in A, at (' + e.a + ',' + e.b + ') and (' + e.b + ',' + e.a + '), where it only records that a link exists. ' +
    'Its D_E = 4 attributes occupy a single column of E; E has one column per edge (7 here, not 36), so edge features are stored sparsely.');
}
function select_node(v) {
  if (v === '') { state.node = null; refresh(); return; }
  state.edge = null;
  var s2 = document.getElementById('selectEdgeInput'); if (s2) s2.value = '';
  state.node = +v; refresh();
}
function select_edge(v) {
  if (v === '') { state.edge = null; refresh(); return; }
  state.node = null;
  var s1 = document.getElementById('selectNodeInput'); if (s1) s1.value = '';
  state.edge = +v; refresh();
}
function toggle_panelFocus(v) { state.focus = v; refresh(); }
function trigger_clear() {
  state.node = null; state.edge = null;
  var s1 = document.getElementById('selectNodeInput'); if (s1) s1.value = '';
  var s2 = document.getElementById('selectEdgeInput'); if (s2) s2.value = '';
  hidePopup(); refresh();
}

/* =====================  DEMO STEPS  ===================== */
var steps = [
  {
    title: 'The graph itself',
    narr: 'Six nodes joined by seven undirected edges. Each node carries a D-dimensional feature vector (orange stack) and each edge a D_E-dimensional vector (teal stack) — the picture holds all the information, but a network cannot consume a picture.',
    focus: 'all', node: null, edge: null
  },
  {
    title: 'Connectivity becomes a matrix',
    narr: 'The adjacency matrix A puts a 1 wherever two nodes share an edge. It is N × N, symmetric because edges are undirected, and zero on the diagonal because no node links to itself.',
    focus: 'b', node: null, edge: null
  },
  {
    title: 'Click a node: a row, a column, a feature vector',
    narr: 'Node 3 (the hub) is selected. Its row and its column in A light up, showing four neighbours mirrored across the diagonal, and column 3 of X lights up — the one place its attributes live.',
    focus: 'all', node: 3, edge: null
  },
  {
    title: 'Node attributes live in X',
    narr: 'X is D × N: one column per node, one row per feature channel. Node ordering here is arbitrary but must match the ordering used by A.',
    focus: 'c', node: 3, edge: null
  },
  {
    title: 'Click an edge: one column of E, two cells of A',
    narr: 'Edge 3–4 is selected. A single column of E holds its attributes, while the same edge appears twice in A, at (3,4) and (4,3). E has E columns — seven, not thirty-six — so edge features are stored sparsely.',
    focus: 'd', node: null, edge: 3
  },
  {
    title: 'Three matrices, one graph',
    narr: 'Together A, X and E reconstruct the drawing exactly: structure, node attributes, edge attributes. This triple is the standard input to a graph neural network.',
    focus: 'all', node: null, edge: null
  }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = ((i % steps.length) + steps.length) % steps.length;
  var s = steps[stepIdx];
  state.focus = s.focus; state.node = s.node; state.edge = s.edge;
  var pf = document.getElementById('panelFocusInput'); if (pf) pf.value = s.focus;
  var sn = document.getElementById('selectNodeInput'); if (sn) sn.value = s.node === null ? '' : String(s.node);
  var seI = document.getElementById('selectEdgeInput'); if (seI) seI.value = s.edge === null ? '' : String(s.edge);
  var st = document.getElementById('stepTitle'); if (st) st.textContent = s.title;
  var nr = document.getElementById('demoNarration'); if (nr) nr.textContent = s.narr;
  var sl = document.getElementById('stepLabel'); if (sl) sl.textContent = (stepIdx + 1) + ' / ' + steps.length;
  refresh();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

