<span id="stepTitle" style="font-weight:600;font-size:11.5px;color:#25506a"></span>
<span id="demoNarration" style="display:block;font-size:11px;line-height:1.45;color:#333"></span>
<span style="display:flex;align-items:center;gap:8px">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="font-size:11px"></span>
  <button onclick="nextStep()">▶</button>
</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var VW = 1200, VH = 865;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, VW, VH).attr('preserveAspectRatio', 'xMidYMid meet');

var C = {
  rust: '#8c3a24', rustText: '#a8442a',
  slate: '#5b7f96', slateFill: '#4a7691', slateText: '#40758c',
  tealText: '#2f9080',
  grey: '#3a3a3a', cellEdge: '#b9c3c9',
  acc: '#ef9a1e'
};

var ORANGES = ['#f4cdb6', '#eda87f', '#e08a5a', '#cf6b3a', '#b8491c', '#a33c14', '#7a2a10', '#d98055'];
var TEALS = ['#d3ece6', '#a8dbd2', '#79c7ba', '#4db2a2', '#2a9585', '#17756a', '#3fb3a0'];

/* ---------- text helper (supports bold / italic / subscript runs) ---------- */
function richLabel(parent, parts, x, y, o) {
  o = o || {};
  var size = o.size || 22;
  var t = parent.text(function (add) {
    for (var i = 0; i < parts.length; i++) {
      var p = parts[i];
      var s = add.tspan(p.t);
      var f = {};
      if (p.bold) f.weight = 'bold';
      if (p.italic) f.style = 'italic';
      if (p.sub) f.size = size * 0.72;
      s.font(f);
    }
  });
  t.font({ family: 'sans-serif', size: size, anchor: o.anchor || 'middle', weight: o.weight || 'normal', leading: 1 });
  t.fill(o.fill || C.grey);
  t.attr('x', x); t.attr('y', y);
  var kids = t.children(), cum = 0;
  for (var i = 0; i < kids.length; i++) {
    var want = (parts[i] && parts[i].sub) ? size * 0.25 : 0;
    kids[i].attr('dy', want - cum); cum = want;
    if (i === 0) kids[i].attr('x', x); else kids[i].attr('x', null);
  }
  t.css('pointer-events', 'none');
  return t;
}
function sq(g, x, y, s, fill) {
  return g.rect(s, s).radius(Math.max(2, s * 0.18)).move(x, y).fill(fill).stroke({ width: 0 });
}

/* ---------- data ---------- */
var nodes = [
  { id: 1, x: 255, y: 98, sx: 280, sy: 18 },
  { id: 2, x: 53, y: 121, sx: 93, sy: 56 },
  { id: 3, x: 147, y: 291, sx: 107, sy: 308 },
  { id: 4, x: 433, y: 123, sx: 469, sy: 37 },
  { id: 5, x: 556, y: 249, sx: 595, sy: 209 },
  { id: 6, x: 334, y: 436, sx: 367, sy: 399 }
];
var edges = [
  { a: 1, b: 3, sx: 238, sy: 143 },
  { a: 1, b: 4, sx: 353, sy: 35 },
  { a: 2, b: 3, sx: 66, sy: 178 },
  { a: 3, b: 4, sx: 296, sy: 216 },
  { a: 3, b: 6, sx: 204, sy: 355 },
  { a: 4, b: 5, sx: 528, sy: 134 },
  { a: 5, b: 6, sx: 440, sy: 353 }
];
var nodeFeat = {
  1: [1, 5, 3, 6, 0], 2: [2, 4, 6, 3, 5], 3: [0, 1, 6, 4, 2],
  4: [6, 5, 2, 6, 3], 5: [7, 4, 5, 2, 6], 6: [3, 2, 6, 1, 5]
};
var edgeFeat = [
  [5, 0, 1, 2], [3, 0, 2, 5], [1, 2, 0, 4], [2, 4, 5, 3],
  [0, 1, 3, 6], [4, 2, 0, 1], [1, 0, 2, 3]
];
function nodeById(id) { for (var i = 0; i < nodes.length; i++) { if (nodes[i].id === id) return nodes[i]; } return null; }
function edgeIndex(a, b) {
  for (var k = 0; k < edges.length; k++) {
    if ((edges[k].a === a && edges[k].b === b) || (edges[k].a === b && edges[k].b === a)) return k;
  }
  return -1;
}
function degree(id) { var d = 0; for (var k = 0; k < edges.length; k++) { if (edges[k].a === id || edges[k].b === id) d++; } return d; }

var state = { focus: 'all', node: null, edge: null };

/* ---------- panel groups ---------- */
var gGraph = draw.group();
var gAdj = draw.group();
var gX = draw.group();
var gE = draw.group();

var PANELS = {
  a: { g: gGraph, box: [0, 0, 650, 522] },
  b: { g: gAdj, box: [650, 0, 550, 522] },
  c: { g: gX, box: [0, 522, 650, 343] },
  d: { g: gE, box: [650, 522, 550, 343] }
};

/* =====================  PANEL a) GRAPH  ===================== */
richLabel(gGraph, [{ t: 'a)' }], 12, 42, { size: 30, anchor: 'start', fill: C.grey });

var edgeEls = [], nodeEls = [];
var gEdgeLines = gGraph.group();
var gEdgeStacks = gGraph.group();
var gNodes = gGraph.group();
var graphRings = gGraph.group();

var SS = 15, SP = 18;

for (var k = 0; k < edges.length; k++) {
  (function (k) {
    var e = edges[k];
    var A = nodeById(e.a), B = nodeById(e.b);
    var eg = gEdgeLines.group();
    var line = eg.line(A.x, A.y, B.x, B.y).stroke({ color: C.slate, width: 3, linecap: 'round' });
    var hit = eg.line(A.x, A.y, B.x, B.y).stroke({ color: '#000', width: 16, opacity: 0 }).css('cursor', 'pointer');
    var sg = gEdgeStacks.group();
    for (var r = 0; r < 4; r++) {
      var rc = sq(sg, e.sx, e.sy + r * SP, SS, TEALS[edgeFeat[k][r]]).css('cursor', 'pointer');
      (function (r, rc) {
        rc.on('mousemove', function (ev) {
          showTooltip('Edge ' + e.a + '–' + e.b + ', feature ' + (r + 1) + '  →  E[' + (r + 1) + ', col ' + (k + 1) + ']', ev);
        }).on('mouseleave', hideTooltip).on('click', function () { pickEdge(k); });
      })(r, rc);
    }
    var ring = graphRings.rect(SS + 8, 4 * SP - (SP - SS) + 8).radius(6).move(e.sx - 4, e.sy - 4)
      .fill('none').stroke({ color: C.acc, width: 3 }).opacity(0);
    hit.on('mousemove', function (ev) {
      showTooltip('Edge ' + e.a + '–' + e.b + ' · one column of E · cells (' + e.a + ',' + e.b + ') and (' + e.b + ',' + e.a + ') of A', ev);
    }).on('mouseleave', hideTooltip).on('click', function () { pickEdge(k); });
    edgeEls.push({ g: eg, sg: sg, line: line, ring: ring });
  })(k);
}

for (var i = 0; i < nodes.length; i++) {
  (function (nd) {
    var ng = gNodes.group();
    var sg = gNodes.group();
    for (var r = 0; r < 5; r++) {
      var rc = sq(sg, nd.sx, nd.sy + r * SP, SS, ORANGES[nodeFeat[nd.id][r]]).css('cursor', 'pointer');
      (function (r, rc) {
        rc.on('mousemove', function (ev) {
          showTooltip('Node ' + nd.id + ', feature ' + (r + 1) + '  →  X[' + (r + 1) + ', ' + nd.id + ']', ev);
        }).on('mouseleave', hideTooltip).on('click', function () { pickNode(nd.id); });
      })(r, rc);
    }
    var circ = ng.circle(48).center(nd.x, nd.y).fill('#ffffff').stroke({ color: C.rust, width: 3.2 }).css('cursor', 'pointer');
    richLabel(ng, [{ t: String(nd.id) }], nd.x, nd.y + 8, { size: 24, fill: C.grey });
    var ring = graphRings.rect(SS + 8, 5 * SP - (SP - SS) + 8).radius(6).move(nd.sx - 4, nd.sy - 4)
      .fill('none').stroke({ color: C.acc, width: 3 }).opacity(0);
    circ.on('mousemove', function (ev) {
      showTooltip('Node ' + nd.id + ' · degree ' + degree(nd.id) + ' · row & column ' + nd.id + ' of A, column ' + nd.id + ' of X', ev);
    }).on('mouseleave', hideTooltip).on('click', function () { pickNode(nd.id); });
    nodeEls.push({ id: nd.id, g: ng, sg: sg, circle: circ, ring: ring });
  })(nodes[i]);
}

/* =====================  PANEL b) ADJACENCY  ===================== */
var ADJ = { x: 830, y: 272, c: 32, p: 40 };
var adjCx = ADJ.x + (6 * ADJ.p - (ADJ.p - ADJ.c)) / 2;
richLabel(gAdj, [{ t: 'b)' }], 668, 42, { size: 30, anchor: 'start', fill: C.grey });
richLabel(gAdj, [{ t: 'Adjacency' }], adjCx, 148, { size: 27, fill: C.slateText });
richLabel(gAdj, [{ t: 'matrix, ' }, { t: 'A', bold: true }], adjCx, 186, { size: 27, fill: C.slateText });
richLabel(gAdj, [{ t: 'N', italic: true }, { t: ' × ' }, { t: 'N', italic: true }], adjCx, 224, { size: 25, fill: C.slateText });

var adjCells = [], adjColHead = {}, adjRowHead = {};
var gAdjCells = gAdj.group();
var adjRings = gAdj.group();

for (var i3 = 1; i3 <= 6; i3++) {
  for (var j3 = 1; j3 <= 6; j3++) {
    (function (i, j) {
      var ei = edgeIndex(i, j);
      var v = (ei >= 0) ? 1 : 0;
      var x = ADJ.x + (j - 1) * ADJ.p, y = ADJ.y + (i - 1) * ADJ.p;
      var r = gAdjCells.rect(ADJ.c, ADJ.c).radius(5).move(x, y)
        .fill(v ? C.slateFill : '#ffffff')
        .stroke({ color: v ? C.slateFill : C.cellEdge, width: 2 })
        .css('cursor', 'pointer');
      r.on('mousemove', function (ev) {
        var msg;
        if (v) {
          msg = 'A[' + i + ',' + j + '] = 1 — nodes ' + i + ' and ' + j + ' are connected';
        } else if (i === j) {
          msg = 'A[' + i + ',' + i + '] = 0 — the diagonal is empty: a node is not its own neighbour';
        } else {
          msg = 'A[' + i + ',' + j + '] = 0 — no edge between nodes ' + i + ' and ' + j;
        }
        showTooltip(msg, ev);
      }).on('mouseleave', hideTooltip)
        .on('click', function () { if (v) { pickEdge(ei); } else { pickNode(i); } });
      adjCells.push({ r: r, i: i, j: j, v: v });
    })(i3, j3);
  }
}
for (var j = 1; j <= 6; j++) {
  adjColHead[j] = richLabel(gAdj, [{ t: String(j) }], ADJ.x + (j - 1) * ADJ.p + ADJ.c / 2, ADJ.y - 13, { size: 23, fill: C.grey });
}
for (var i2 = 1; i2 <= 6; i2++) {
  adjRowHead[i2] = richLabel(gAdj, [{ t: String(i2) }], ADJ.x - 13, ADJ.y + (i2 - 1) * ADJ.p + 24, { size: 23, anchor: 'end', fill: C.grey });
}

/* =====================  PANEL c) NODE DATA X  ===================== */
var XM = { x: 370, y: 612, c: 32, p: 40 };
richLabel(gX, [{ t: 'c)' }], 20, 566, { size: 30, anchor: 'start', fill: C.grey });
richLabel(gX, [{ t: 'Node' }], 340, 662, { size: 27, anchor: 'end', fill: C.rustText });
richLabel(gX, [{ t: 'data, ' }, { t: 'X', bold: true }], 340, 700, { size: 27, anchor: 'end', fill: C.rustText });
richLabel(gX, [{ t: 'D', italic: true }, { t: ' × ' }, { t: 'N', italic: true }], 340, 738, { size: 25, anchor: 'end', fill: C.rustText });

var xCells = [], xColHead = {};
var gXCells = gX.group();
var xRings = gX.group();
for (var r4 = 1; r4 <= 5; r4++) {
  for (var c4 = 1; c4 <= 6; c4++) {
    (function (row, col) {
      var x = XM.x + (col - 1) * XM.p, y = XM.y + (row - 1) * XM.p;
      var rc = gXCells.rect(XM.c, XM.c).radius(5).move(x, y)
        .fill(ORANGES[nodeFeat[col][row - 1]]).stroke({ width: 0 }).css('cursor', 'pointer');
      rc.on('mousemove', function (ev) {
        showTooltip('X[' + row + ',' + col + '] — feature ' + row + ' of node ' + col, ev);
      }).on('mouseleave', hideTooltip).on('click', function () { pickNode(col); });
      xCells.push({ r: rc, row: row, col: col });
    })(r4, c4);
  }
}
for (var j4 = 1; j4 <= 6; j4++) {
  xColHead[j4] = richLabel(gX, [{ t: String(j4) }], XM.x + (j4 - 1) * XM.p + XM.c / 2, XM.y - 13, { size: 23, fill: C.grey });
}

/* =====================  PANEL d) EDGE DATA E  ===================== */
var EM = { x: 912, y: 652, c: 32, p: 40 };
richLabel(gE, [{ t: 'd)' }], 668, 566, { size: 30, anchor: 'start', fill: C.grey });
richLabel(gE, [{ t: 'Edge' }], 882, 692, { size: 27, anchor: 'end', fill: C.tealText });
richLabel(gE, [{ t: 'data, ' }, { t: 'E', bold: true }], 882, 730, { size: 27, anchor: 'end', fill: C.tealText });
richLabel(gE, [{ t: 'D', italic: true }, { t: 'E', italic: true, sub: true }, { t: ' × ' }, { t: 'E', italic: true }], 882, 768, { size: 25, anchor: 'end', fill: C.tealText });

var eCells = [], eColHeadA = {}, eColHeadB = {};
var gECells = gE.group();
var eRings = gE.group();
for (var r5 = 1; r5 <= 4; r5++) {
  for (var c5 = 0; c5 < edges.length; c5++) {
    (function (row, col) {
      var x = EM.x + col * EM.p, y = EM.y + (row - 1) * EM.p;
      var rc = gECells.rect(EM.c, EM.c).radius(5).move(x, y)
        .fill(TEALS[edgeFeat[col][row - 1]]).stroke({ width: 0 }).css('cursor', 'pointer');
      rc.on('mousemove', function (ev) {
        showTooltip('E[' + row + ',' + (col + 1) + '] — feature ' + row + ' of edge ' + edges[col].a + '–' + edges[col].b, ev);
      }).on('mouseleave', hideTooltip).on('click', function () { pickEdge(col); });
      eCells.push({ r: rc, row: row, col: col });
    })(r5, c5);
  }
}
for (var kk = 0; kk < edges.length; kk++) {
  var hx = EM.x + kk * EM.p + EM.c / 2;
  eColHeadA[kk] = richLabel(gE, [{ t: String(edges[kk].a) }], hx, EM.y - 47, { size: 23, fill: C.grey });
  eColHeadB[kk] = richLabel(gE, [{ t: String(edges[kk].b) }], hx, EM.y - 15, { size: 23, fill: C.grey });
}

/* =====================  HIGHLIGHT LOGIC  ===================== */
function ringRect(g, x, y, w, h, strong) {
  return g.rect(w, h).radius(7).move(x, y).fill('none')
    .stroke({ color: C.acc, width: strong ? 4 : 2.5, opacity: strong ? 1 : 0.7 });
}

function applyFocus() {
  var f = state.focus;
  var keys = ['a', 'b', 'c', 'd'];
  for (var i = 0; i < keys.length; i++) {
    var p = PANELS[keys[i]];
    var on = (f === 'all' || f === keys[i]);
    if (on) { p.g.show(); p.g.opacity(1); } else { p.g.hide(); }
  }
  var box = (f === 'all') ? [0, 0, VW, VH] : PANELS[f].box;
  draw.viewbox(box[0], box[1], box[2], box[3]);
}

function refresh() {
  applyFocus();

  var n = state.node, ek = state.edge;
  var se = (ek !== null) ? edges[ek] : null;
  var sel = (n !== null) || (se !== null);

  /* --- panel a) graph --- */
  for (var a = 0; a < nodeEls.length; a++) {
    var ne = nodeEls[a];
    var hi = (n === ne.id) || (se && (se.a === ne.id || se.b === ne.id));
    ne.g.opacity(sel && !hi ? 0.18 : 1);
    ne.sg.opacity(sel && !hi ? 0.18 : 1);
    ne.circle.stroke({ color: (n === ne.id) ? C.acc : C.rust, width: (n === ne.id) ? 5.5 : 3.2 });
    ne.ring.opacity(n === ne.id ? 1 : 0);
  }
  for (var b = 0; b < edgeEls.length; b++) {
    var ee = edgeEls[b];
    var hiE = (ek === b) || (n !== null && (edges[b].a === n || edges[b].b === n));
    ee.g.opacity(sel && !hiE ? 0.15 : 1);
    ee.sg.opacity(sel && !hiE ? 0.15 : 1);
    ee.line.stroke({ color: (ek === b) ? C.acc : C.slate, width: (ek === b) ? 5 : 3 });
    ee.ring.opacity(ek === b ? 1 : 0);
  }

  /* --- panel b) adjacency --- */
  adjRings.clear();
  for (var c = 0; c < adjCells.length; c++) {
    var cc = adjCells[c];
    var hiC = false;
    if (n !== null && (cc.i === n || cc.j === n)) hiC = true;
    if (se && ((cc.i === se.a && cc.j === se.b) || (cc.i === se.b && cc.j === se.a))) hiC = true;
    cc.r.opacity(sel && !hiC ? 0.2 : 1);
  }
  for (var h = 1; h <= 6; h++) {
    var onH = (n === h) || (se && (se.a === h || se.b === h));
    adjColHead[h].fill(onH ? C.acc : C.grey).font({ weight: onH ? 'bold' : 'normal' });
    adjRowHead[h].fill(onH ? C.acc : C.grey).font({ weight: onH ? 'bold' : 'normal' });
  }
  var gw = 5 * ADJ.p + ADJ.c;
  if (n !== null) {
    ringRect(adjRings, ADJ.x - 5, ADJ.y + (n - 1) * ADJ.p - 5, gw + 10, ADJ.c + 10, true);
    ringRect(adjRings, ADJ.x + (n - 1) * ADJ.p - 5, ADJ.y - 5, ADJ.c + 10, gw + 10, true);
  }
  if (se) {
    ringRect(adjRings, ADJ.x + (se.b - 1) * ADJ.p - 5, ADJ.y + (se.a - 1) * ADJ.p - 5, ADJ.c + 10, ADJ.c + 10, true);
    ringRect(adjRings, ADJ.x + (se.a - 1) * ADJ.p - 5, ADJ.y + (se.b - 1) * ADJ.p - 5, ADJ.c + 10, ADJ.c + 10, true);
  }

  /* --- panel c) node data X --- */
  xRings.clear();
  for (var d = 0; d < xCells.length; d++) {
    var xc = xCells[d];
    var hiX = (n === xc.col) || (se && (se.a === xc.col || se.b === xc.col));
    xc.r.opacity(sel && !hiX ? 0.2 : 1);
  }
  for (var hh = 1; hh <= 6; hh++) {
    var onX = (n === hh) || (se && (se.a === hh || se.b === hh));
    xColHead[hh].fill(onX ? C.acc : C.grey).font({ weight: onX ? 'bold' : 'normal' });
  }
  var xh = 4 * XM.p + XM.c;
  if (n !== null) ringRect(xRings, XM.x + (n - 1) * XM.p - 5, XM.y - 5, XM.c + 10, xh + 10, true);
  if (se) {
    ringRect(xRings, XM.x + (se.a - 1) * XM.p - 5, XM.y - 5, XM.c + 10, xh + 10, false);
    ringRect(xRings, XM.x + (se.b - 1) * XM.p - 5, XM.y - 5, XM.c + 10, xh + 10, false);
  }

  /* --- panel d) edge data E --- */
  eRings.clear();
  for (var g2 = 0; g2 < eCells.length; g2++) {
    var ec = eCells[g2];
    var inc = (n !== null && (edges[ec.col].a === n || edges[ec.col].b === n));
    var hiEE = (ek === ec.col) || inc;
    ec.r.opacity(sel && !hiEE ? 0.2 : 1);
  }
  for (var m = 0; m < edges.length; m++) {
    var onE = (ek === m) || (n !== null && (edges[m].a === n || edges[m].b === n));
    eColHeadA[m].fill(onE ? C.acc : C.grey).font({ weight: onE ? 'bold' : 'normal' });
    eColHeadB[m].fill(onE ? C.acc : C.grey).font({ weight: onE ? 'bold' : 'normal' });
  }
  var eh = 3 * EM.p + EM.c;
  if (ek !== null) ringRect(eRings, EM.x + ek * EM.p - 5, EM.y - 5, EM.c + 10, eh + 10, true);
  if (n !== null) {
    for (var q = 0; q < edges.length; q++) {
      if (edges[q].a === n || edges[q].b === n) ringRect(eRings, EM.x + q * EM.p - 5, EM.y - 5, EM.c + 10, eh + 10, false);
    }
  }

  /* --- side info --- */
  var info = document.getElementById('selInfo');
  if (info) {
    if (n !== null) {
      info.textContent = 'Node ' + n + ': row ' + n + ' AND column ' + n + ' of A (mirror images), column ' + n + ' of X, and ' + degree(n) + ' columns of E.';
    } else if (se) {
      info.textContent = 'Edge ' + se.a + '–' + se.b + ': column ' + (ek + 1) + ' of E, plus the two cells (' + se.a + ',' + se.b + ') & (' + se.b + ',' + se.a + ') of A.';
    } else {
      info.textContent = '';
    }
  }
}

/* =====================  INTERACTION  ===================== */
function pickNode(id) {
  state.node = id; state.edge = null;
  var s1 = document.getElementById('selectNodeInput'); if (s1) s1.value = String(id);
  var s2 = document.getElementById('selectEdgeInput'); if (s2) s2.value = '';
  refresh();
  showPopup('Node ' + id,
    'Node ' + id + ' has degree ' + degree(id) + '. In the adjacency matrix A it owns row ' + id + ' AND column ' + id +
    ' — the two are mirror images because the edges are undirected, and A[' + id + ',' + id + '] = 0 since a node is not its own neighbour. ' +
    'Its D = 5 attributes live in exactly one place: column ' + id + ' of the node data matrix X.');
}
function pickEdge(k) {
  state.edge = k; state.node = null;
  var s1 = document.getElementById('selectNodeInput'); if (s1) s1.value = '';
  var s2 = document.getElementById('selectEdgeInput'); if (s2) s2.value = String(k);
  refresh();
  var e = edges[k];
  showPopup('Edge ' + e.a + '–' + e.b,
    'Connectivity and attributes are stored separately. This edge appears twice in A, at (' + e.a + ',' + e.b + ') and (' + e.b + ',' + e.a + '), where it records only that a link exists. ' +
    'Its D_E = 4 attributes occupy a single column of E; E has one column per edge (7 here, not 36), so edge features are stored sparsely.');
}
function select_node(v) {
  if (v === '') { state.node = null; refresh(); return; }
  state.edge = null;
  var s2 = document.getElementById('selectEdgeInput'); if (s2) s2.value = '';
  state.node = +v; refresh();
}
function select_edge(v) {
  if (v === '') { state.edge = null; refresh(); return; }
  state.node = null;
